args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?death WHERE {
  VALUES ?film { dbr:The_Hitler_Gang dbr:Flannelfoot }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?dDate . }
  OPTIONAL { ?director dbo:deathYear ?dYear . }
  OPTIONAL { ?director dbp:deathDate ?dMonthDay . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }

  BIND(
    IF(BOUND(?dDate), ?dDate,
      IF(BOUND(?dYear) && BOUND(?dMonthDay),
         xsd:date(CONCAT(STR(?dYear), "-", SUBSTR(STR(?dMonthDay), 3))),
         IF(BOUND(?dYear),
            xsd:date(CONCAT(STR(?dYear), "-01-01")),
            (UNDEF)
         )
      )
    ) AS ?death)
}
ORDER BY ?death
LIMIT 1

